local _, ns = ...
-- Original summaries. Classic-derived reference texts, cross-checked
-- against IDs present in the installed Forever database. The current
-- quest description must match every anchor before any summary is used.
ns.Stories[99] = { anchors = { "Arugal", "Piroleña" }, text = "La investigación ya apunta a la maldición que transforma a los habitantes de Aldea Piroleña al caer la noche. Recuperas los grilletes encantados para que puedan estudiar cómo Arugal los mantiene sujetos a esa magia y comprender su extraño comportamiento." }
ns.Stories[100] = { anchors = { "espíritus corruptos", "conjuro" }, text = "El ritual ha consumido los últimos restos de agua y disipado a los espíritus corruptos. El siguiente encuentro permite hablar con la manifestación que aparece tras la purificación del santuario." }
ns.Stories[354] = { anchors = { "Agamand", "empleados" }, text = "La familia Agamand convenció a sus trabajadores de permanecer en los molinos cuando llegó la peste, y todos acabaron atrapados en la tragedia. Ahora sus antiguos empleadores sirven a la Plaga: el encargo mezcla la defensa de los Renegados con la venganza de quien los culpa por su muerte." }
ns.Stories[355] = { anchors = { "Sevren", "amenaza" }, text = "Tu intervención contra los Agamand llamó la atención del magistrado Sevren. Lo que comenzó como una venganza personal también afecta a la seguridad de Tirisfal, porque los molinos siguen siendo una amenaza para todos los Renegados." }
ns.Stories[356] = { anchors = { "Baluarte", "suministros" }, text = "El Baluarte contiene a la Plaga en la frontera, pero algunos enemigos consiguen infiltrarse en Tirisfal. Tu patrulla protege la retaguardia y los suministros de sus defensores para evitar que tengan que combatir en dos frentes." }
ns.Stories[357] = { anchors = { "exánime", "libro de hechizos" }, text = "Un exánime independiente ataca a quienes se acercan porque cree que todos los demás no muertos siguen esclavizados por la Plaga. Bethor quiere conocer su identidad y sus conocimientos: robar su libro permitiría averiguar si puede convertirse en un aliado de los Renegados." }
ns.Stories[358] = { anchors = { "Putrepellejo", "cadáveres" }, text = "La Plaga está vaciando las fosas comunes de Tirisfal para obtener nuevos soldados. Al enfrentarte a los gnolls Putrepellejo, intentas cortar ese suministro de cadáveres antes de que las víctimas de la peste vuelvan a servir al enemigo." }
ns.Stories[359] = { anchors = { "Baluarte", "Linnea" }, text = "Sevren necesita noticias del puesto de la Guardia de la Muerte que vigila la frontera. Buscas el informe de Linnea para saber si la Plaga ha logrado atravesar El Baluarte y afianzarse dentro de Tirisfal." }
ns.Stories[360] = { anchors = { "Sevren", "información" }, text = "La vigilancia de Tirisfal depende de que las noticias del frente lleguen a tiempo. Llevas al magistrado Sevren el informe que acabas de recibir para que pueda responder a los movimientos de la Plaga." }
ns.Stories[361] = { anchors = { "Thurman", "Yvette" }, text = "La carta de Thurman, el hijo mayor de Gregor Agamand, está dirigida a Yvette Farthing y parece no haber llegado a sus manos. Encontrar a la destinataria permitiría completar esa entrega pendiente." }
ns.Stories[362] = { anchors = { "Devlin", "Peste" }, text = "Devlin Agamand sucumbió a la peste y todavía ronda los antiguos molinos de su familia. Te piden reunir sus restos como parte del ajuste de cuentas con los Agamand, cuya historia sigue atormentando a quienes sobrevivieron como Renegados." }
ns.Stories[363] = { anchors = { "Mordo", "Sarvis" }, text = "Acabas de despertar en Camposanto con tu voluntad recuperada: ya no eres un siervo del Rey Exánime. Mordo te envía con Sarvis para que comprendas tu nueva condición y encuentres tu lugar entre los Renegados, que luchan por conservar esa libertad." }
ns.Stories[364] = { anchors = { "Renegados", "Rey Exánime" }, text = "Haber recuperado la voluntad te separa de los no muertos que todavía obedecen al Rey Exánime. Los autómatas que invadieron Camposanto siguen siendo sus siervos; combatirlos protege el asentamiento y marca tu primera colaboración con los Renegados." }
ns.Stories[365] = { anchors = { "calabazas", "Johaan" }, text = "Te mandan a robar alimentos de una plantación humana vigilada por la Cruzada Escarlata. Las calabazas deben llegar al boticario Johaan: el encargo sirve como una primera prueba de lealtad a los métodos y los intereses de los Renegados." }
ns.Stories[366] = { anchors = { "Gunther", "Kirin Tor" }, text = "Bethor reconoció a Gunther, un antiguo compañero del Kirin Tor que también escapó del control del Rey Exánime. Devuelves el libro con una señal mágica de esa libertad para intentar convencer al exánime de que se una a los Renegados." }
ns.Stories[367] = { anchors = { "Sylvanas", "sangre" }, text = "Sylvanas ha encargado a la Sociedad Real de Boticarios crear una peste más mortífera que cualquier enfermedad conocida para destruir al ejército de Arthas. Johaan necesita sangre de canoscuro para comprobar si puede ser la clave de esa nueva fórmula." }
ns.Stories[368] = { anchors = { "enfermedad", "escamas" }, text = "Johaan necesita que su enfermedad pueda propagarse, además de envenenar a víctimas aisladas. Las muestras de los múrlocs forman parte de esa investigación: busca convertir una fórmula mortal en una peste de mayor alcance." }
ns.Stories[369] = { anchors = { "veneno", "nocturácnidas" }, text = "Un antiguo texto vincula una epidemia devastadora con el veneno de ciertas arañas. Johaan quiere comprobar si ese agente contagioso puede incorporarse a su nueva peste, y tus muestras hacen posible continuar el experimento." }
ns.Stories[370] = { anchors = { "Perrine", "documentos" }, text = "La información interceptada reveló la posición de una fuerza de la Cruzada Escarlata dirigida por Perrine. Te envían a desarticular ese destacamento como parte de la ofensiva de los Renegados contra una organización que persigue a los no muertos." }
ns.Stories[371] = { anchors = { "Vachon", "Cruzada Escarlata" }, text = "Los informes sitúan al capitán Vachon al frente de otro foco de ataques escarlata cerca de la Hacienda Balnir. Tu intervención busca debilitar esa posición antes de que la Cruzada consolide su presencia en Tirisfal." }
ns.Stories[372] = { anchors = { "Melrache", "Dama Oscura" }, text = "La ofensiva continúa contra el puesto escarlata del capitán Melrache. Te confían atacar a su mando y su guardia como parte de la lucha por controlar las antiguas torres de Tirisfal en nombre de la Dama Oscura." }
ns.Stories[374] = { anchors = { "Varimathras", "anillos" }, text = "Varimathras exige pruebas de tu participación contra la Cruzada Escarlata. Los anillos identifican a sus miembros caídos y permiten presentar tu servicio como una demostración de lealtad a la dirección de los Renegados." }
ns.Stories[375] = { anchors = { "frío", "manta" }, text = "Gretchen siente que el frío de la no-muerte deteriora su cuerpo y teme perder la razón. Necesita pieles de murciélago y hilo para coserse una manta y poder seguir sirviendo a la causa de Sylvanas." }
ns.Stories[376] = { anchors = { "Sarvis", "armadura" }, text = "Quienes sostienen Camposanto deben atender heridos, equipar reclutas y ayudar a Sarvis. Reúnes recursos de los animales cercanos para obtener protección y contribuir al abastecimiento de una comunidad que intenta mantenerse en pie." }
ns.Stories[380] = { anchors = { "oro", "arañas" }, text = "Camposanto necesita recursos para sobrevivir, pero las arañas han ocupado una de sus fuentes de oro. Despejar la mina permite recuperar ese recurso con el escaso personal disponible: tu ayuda sostiene al asentamiento, además de eliminar una amenaza." }
ns.Stories[382] = { anchors = { "mensajero", "información" }, text = "Un agente escarlata salió del monasterio con información que los Renegados consideran importante. Interceptarlo puede revelar las intenciones de la Cruzada y dar a Camposanto una ventaja frente a quienes lo amenazan." }
ns.Stories[383] = { anchors = { "Zygand", "información" }, text = "La información interceptada debe llegar al ejecutor Zygand para orientar la ofensiva contra la Cruzada Escarlata. Tu servicio en Camposanto te lleva ahora a Rémol, donde el mando local puede aprovechar tanto esos documentos como tu ayuda." }
ns.Stories[398] = { anchors = { "Ojo de cresa", "cuerpos" }, text = "Ojo de cresa está robando cadáveres para alimentar las filas del Rey Exánime. La orden de Rémol busca cortar esa colaboración con la Plaga y exige una prueba para confirmar que el responsable ya no puede seguir haciéndolo." }
ns.Stories[404] = { anchors = { "Plaga", "Rémol" }, text = "La Plaga ha ocupado los alrededores del puente viejo, cerca de Rémol. Te piden intervenir contra esos muertos para frenar la amenaza inmediata al asentamiento y demostrar el resultado a la Guardia de la Muerte." }
ns.Stories[405] = { anchors = { "Bethor", "exánime" }, text = "Bethor Duroyelo necesita un agente que haya demostrado su valía contra la Plaga. Sevren te envía a Entrañas con sus órdenes para una misión peligrosa relacionada con el reclutamiento de un exánime independiente." }
ns.Stories[407] = { anchors = { "calabaza", "zelote" }, text = "Johaan ha convertido una de las calabazas robadas en un vehículo para su fórmula. Ahora te pide dársela a un prisionero escarlata: el recado te hace participar directamente en los experimentos con los que busca armar a la Dama Oscura." }
ns.Stories[408] = { anchors = { "Dargol", "ancestros" }, text = "El capitán Dargol usa la cripta de los Agamand como puesto de mando y está levantando a sus antepasados mediante nigromancia. Debes impedir que esa familia de muertos se convierta en otra fuerza de ataque contra los Renegados." }
ns.Stories[409] = { anchors = { "Bethor", "Lillith" }, text = "El encantamiento de Bethor confirma que no estás sometido al Rey Exánime, pero Gunther aún exige pruebas de tus intenciones. Enfrentarte a Lillith Nefara demostraría que también eres un enemigo de la Plaga." }
ns.Stories[411] = { anchors = { "gema", "Bethor" }, text = "Gunther te confía una gema con la que podrá comunicarse con Bethor. Tu entrega restablece el contacto entre antiguos camaradas y hace posible que intercambien directamente lo que han vivido y aprendido." }
ns.Stories[421] = { anchors = { "Arugal", "Argénteos" }, text = "La magia de Arugal ha sembrado el caos en Argénteos, una región estratégica para los Renegados. Dalar Tejealba necesita combatientes capaces de enfrentarse a sus criaturas y pide demostrar esa capacidad contra los huargen del camino." }
ns.Stories[422] = { anchors = { "Arugal", "Remedio" }, text = "Los Renegados quieren comprender la magia de Arugal para volverla contra él. Recuperar sus escritos permite investigar el origen del desastre, en lugar de limitarse a combatir a las criaturas que dejó tras de sí." }
ns.Stories[423] = { anchors = { "Arugal", "objetos encantados" }, text = "El estudio de los escritos reveló que Arugal reforzaba sus hechizos con objetos encantados. Tus nuevas muestras permitirán examinar ese mecanismo y avanzar en la investigación de la magia que amenaza Argénteos." }
ns.Stories[424] = { anchors = { "Arugal", "Grimson" }, text = "Mientras continúa la investigación, el mando quiere recuperar una mina alcanzada por la corrupción de Arugal. Enfrentarte a Grimson busca eliminar a quien controla ese enclave, que los Renegados necesitan para su avance militar." }
ns.Stories[425] = { anchors = { "Quinn", "Ivar" }, text = "Ivar hirió gravemente a Quinn durante una misión de reconocimiento. Aunque ya recibe ayuda, sigue expuesto a otro ataque; detener al necrófago le daría el tiempo necesario para recuperarse." }
ns.Stories[426] = { anchors = { "Plaga", "Molinos" }, text = "La Plaga intenta convertir los Molinos de Agamand en una base desde la que lanzar más ataques sobre Tirisfal. Tu misión forma parte del esfuerzo por impedir que consolide ese punto de apoyo tan cerca de Rémol." }
ns.Stories[427] = { anchors = { "Arren", "ubicaciones" }, text = "Los documentos obtenidos en Camposanto revelaron dónde opera la Cruzada Escarlata. Como la Guardia de la Muerte también debe contener a la Plaga, te encargan aprovechar esa información para debilitar a los escarlata sin retirar a sus defensores del otro frente." }
ns.Stories[428] = { anchors = { "Rane", "Quinn" }, text = "Dos mortacechadores dejaron de enviar noticias durante su reconocimiento del norte de Argénteos. Buscas a Rane y Quinn para averiguar si siguen con vida y recuperar información sobre lo ocurrido en su misión." }
ns.Stories[429] = { anchors = { "Quinn", "corazones" }, text = "Quinn quedó gravemente herido por Ivar el Hediondo y quizá no se recupere sin ayuda de la alquimia. Los corazones de huargo descoloridos darán al boticario Renferrel los ingredientes para una poción curativa. Llevar ese remedio de regreso ofrece una esperanza para el explorador." }
ns.Stories[430] = { anchors = { "poción", "Quinn" }, text = "Renferrel ha preparado una poción para ayudar a Quinn a recuperarse. El remedio debe llegar hasta el mortacechador herido, que permanece al norte de El Sepulcro, en el lugar donde fue atacado." }
ns.Stories[435] = { anchors = { "lobos", "Rane" }, text = "Los lobos impiden a Erland salir para informar a Rane Yorick. Necesita una escolta, preferiblemente con más compañeros, que lo proteja durante el trayecto hasta su contacto entre los mortacechadores." }
ns.Stories[437] = { anchors = { "Putrepellejo", "Latipesadilla" }, text = "Los asaltos contra los Putrepellejo fracasan porque Latipesadilla interviene con su magia. Eliminar a esa protectora busca romper la ventaja que permite a la Plaga mantener su base en El Campo Muerto." }
ns.Stories[438] = { anchors = { "Plaga", "embarcadero" }, text = "La Plaga ha ocupado un embarcadero defendido por gnolls y otros no muertos. Investigas qué interés tiene ese lugar para el enemigo antes de que los Renegados decidan cómo responder a la ocupación." }
ns.Stories[439] = { anchors = { "anillo", "Deliah" }, text = "Entre los cadáveres aparece la mano de una mujer marcada por la peste. Un anillo lleva grabado el nombre de Deliah; entregárselo a Hadrec permite presentar esa pista hallada en el embarcadero ocupado por la Plaga." }
ns.Stories[440] = { anchors = { "Deliah", "Sevren" }, text = "Quieres averiguar a quién pertenecía el anillo y quién se lo entregó a Deliah. Los registros del magistrado Sevren podrían poner nombres a esa historia, aunque todavía no sabes si queda alguien capaz de reconocerlo." }
ns.Stories[441] = { anchors = { "Deliah", "Raleigh" }, text = "Sevren encontró una posible relación entre Deliah y Raleigh, que vive en Entrañas. Llevas el anillo hasta él para comprobar esa identidad y saber si pertenece a la mujer de su pasado." }
ns.Stories[442] = { anchors = { "Thule", "Fenris" }, text = "Hadrec quiere atacar el principal bastión de la Plaga en el bosque. Thule Corvozarpa es el objetivo de una ofensiva que considera tan peligrosa como necesaria para responder a esa presencia." }
ns.Stories[443] = { anchors = { "Putrepellejo", "icor" }, text = "Antes de atacar Fenris, los Renegados necesitan saber quién crea o controla a los Putrepellejo. Renferrel estudiará el líquido que los mantiene activos para buscar una explicación detrás de esos gnolls no muertos." }
ns.Stories[444] = { anchors = { "icor", "Bethor" }, text = "El análisis encontró brujería y nigromancia en el icor, pero todavía no resuelve el misterio. Llevas una muestra a Bethor porque su experiencia mágica puede complementar el trabajo de los boticarios." }
ns.Stories[445] = { anchors = { "Renferrel", "conocimientos" }, text = "Johaan quiere compartir sus resultados con Renferrel para acelerar el proyecto de la nueva peste. Tu entrega conecta a dos miembros de la Sociedad Real de Boticarios y permite que sus investigaciones avancen juntas." }
ns.Stories[446] = { anchors = { "Thule", "hechizos" }, text = "Bethor identificó la magia de Thule, un antiguo compañero que terminó sirviendo a la Plaga. Sus recuerdos de aquellos hechizos pueden ayudar a contrarrestarlos; llevas esa información a Renferrel para preparar una respuesta." }
ns.Stories[447] = { anchors = { "Faranell", "Nueva Plaga" }, text = "Renferrel busca una mezcla capaz de destruir tanto a la Plaga como a los humanos que los Renegados consideran enemigos. Reúnes ingredientes para que Faranell estudie otra fórmula del proyecto de su nueva enfermedad." }
ns.Stories[448] = { anchors = { "Hadrec", "Fenris" }, text = "Antes del asalto a Fenris, debes presentarte ante Hadrec. El mando podría ofrecer información o equipo útil para una operación que los Renegados consideran decisiva." }
ns.Stories[449] = { anchors = { "Quinn", "informe" }, text = "Aunque Quinn se está recuperando, el resultado del reconocimiento no puede esperar. Llevas a Hadrec el informe de los mortacechadores para que sus observaciones sirvan a los planes de los Renegados en Argénteos." }
ns.Stories[450] = { anchors = { "Berard", "Diario" }, text = "Arugal convirtió al boticario Berard en un siervo sin voluntad propia. Sus antiguos estudios sobre una plaga del lago podrían seguir siendo útiles: recuperas el diario para que el conocimiento no se pierda con él." }
ns.Stories[451] = { anchors = { "Berard", "musgo" }, text = "El diario de Berard señala musgos de las criaturas del lago Lordamere y un tumor raro encontrado en un múrloc. Renferrel pide llevar esas muestras a Faranell para investigar su utilidad en la nueva peste." }
ns.Stories[452] = { anchors = { "Consejo", "Arugal" }, text = "El Consejo Piroleña actúa como instrumento de Arugal para controlar a sus seguidores. Te unes a un ataque que busca romper esa estructura de mando y aprovechar la ausencia del mago." }
ns.Stories[460] = { anchors = { "Alaric", "Thule" }, text = "Alaric fue protegido de la peste por un hechizo de Thule, pero quedó atrapado en una no vida que después se convirtió en tortura. Reunir su cabeza con su cuerpo es su petición de ayuda para escapar de ese abandono." }
ns.Stories[461] = { anchors = { "nicho", "Thule" }, text = "Alaric conoce un escondite que guarda un objeto apreciado por Thule y sus antiguos compañeros, además de algo que podría serte útil. Pide que lleves su cuerpo hasta ese rincón oculto de la fortaleza." }
ns.Stories[477] = { anchors = { "Molino Ámbar", "cajas" }, text = "El apoyo de Dalaran mantiene la resistencia humana en Molino Ámbar, pero los Renegados aún no conocen sus planes. Interceptar uno de sus cargamentos puede revelar por qué los magos dedican recursos a ese lugar remoto." }
ns.Stories[478] = { anchors = { "colgante", "caja" }, text = "Recuperas un extraño colgante de la caja que transportaban los magos de Dalaran. Allister debe recibirlo para continuar la investigación sobre los cargamentos enviados a la zona de Molino Ámbar." }
ns.Stories[479] = { anchors = { "Dalar", "colgantes" }, text = "Dalar busca el origen del poder de los magos de Molino Ámbar. Mientras investiga, retiras sus colgantes para dificultar que continúen el proyecto y dar tiempo a los Renegados para responder." }
ns.Stories[480] = { anchors = { "archimago", "nodo" }, text = "Un archimago dirige la reactivación del nodo de energía y Allister teme que sea demasiado tarde para otra solución. Atacarlo busca detener ese trabajo pese a la protección de sus seguidores." }
ns.Stories[481] = { anchors = { "colgante", "Dalar" }, text = "El colgante recuperado necesita una interpretación mágica. Lo llevas a Dalar para que determine qué relación tiene con los planes de los magos de Molino Ámbar." }
ns.Stories[482] = { anchors = { "nodo", "colgantes" }, text = "Dalar identificó un nodo de energía Ley inactivo bajo Molino Ámbar y sospecha que los magos quieren reactivarlo. Informas a Allister de que los colgantes podrían sostener ese esfuerzo, para que decida cómo frenarlo." }
ns.Stories[491] = { anchors = { "varita", "Bethor" }, text = "La varita unía originalmente las de tres aprendices y simbolizaba su amistad antes de la traición de Thule. Devolvérsela a Bethor recupera un recuerdo de ese pasado que Thule había robado y escondido." }
ns.Stories[492] = { anchors = { "prisioneros", "bebida" }, text = "Johaan quiere probar su nueva fórmula en un montaraz cautivo. Llevar la bebida al prisionero te convierte en partícipe de la experimentación con la que los boticarios buscan desarrollar su arma de peste." }
ns.Stories[493] = { anchors = { "Lydon", "descubrimientos" }, text = "La Sociedad Real de Boticarios está compartiendo resultados para acelerar su nueva plaga. Tu viaje lleva las conclusiones de Argénteos a Lydon, en Molino Tarren, y amplía la colaboración entre los investigadores de Sylvanas." }
ns.Stories[494] = { anchors = { "Lesh", "Darthalia" }, text = "Lesh ha sido enviada a vigilar la localidad de Trabalomas y necesita hacer llegar un aviso urgente al alto ejecutor Darthalia. Te pide actuar como enlace con el mando de Molino Tarren y transmitir su mensaje cuanto antes." }
ns.Stories[496] = { anchors = { "agentes letales", "brebajes" }, text = "Lydon investiga sustancias letales para emplearlas contra los humanos, pero no dispone de tiempo para reunirlas. Busca componentes de animales locales que permitan continuar sus experimentos con nuevas mezclas." }
ns.Stories[498] = { anchors = { "Drull", "Tog'thar" }, text = "Krusk escapó cuando el Sindicato capturó a su grupo durante una misión. Sus compañeros siguen presos en Durnholde y necesitan una intervención para salir del lugar donde fueron derrotados." }
ns.Stories[499] = { anchors = { "elixir de sufrimiento", "Umpi" }, text = "El elixir ya está mezclado y Lydon quiere comprobar su efecto. Su ayudante será el sujeto de una prueba vinculada a las sustancias que prepara contra humanos y miembros de la Plaga." }
ns.Stories[501] = { anchors = { "león de montaña", "poción" }, text = "Lydon cree que la sangre de león puede servir para una nueva mezcla mortal. Su investigación responde al propósito de extender enfermedad y muerte en nombre de la Dama Oscura." }
ns.Stories[502] = { anchors = { "elixir de dolor", "Stanley" }, text = "El elixir preparado con sangre necesita una prueba antes de valorar su utilidad. Lydon elige al perro de una granja como sujeto del experimento y pide administrarle la mezcla." }
ns.Stories[503] = { anchors = { "Gol'dir", "documentos" }, text = "Los documentos recuperados apuntan a una base del Sindicato como lugar de cautiverio de Gol'dir. Krusk necesita que lo encuentres y lo liberes tras un encierro que considera demasiado prolongado." }
ns.Stories[506] = { anchors = { "Aliden", "colgante" }, text = "Gol'dir ha conocido los planes esclavistas de Aliden y visto el colgante que busca el Jefe de Guerra. Esa información debe llegar a Krusk mientras el cautivo prepara su propia salida." }
ns.Stories[508] = { anchors = { "colgante", "recuerdo" }, text = "Elysa entrega el colgante y pide que la dejen en paz, sin conservar recuerdos de su antiguo compañero. Llevarlo a Krusk permite continuar la recuperación del objeto que se estaba buscando." }
ns.Stories[509] = { anchors = { "Morrobarro", "elixir" }, text = "Lydon continúa desarrollando mezclas para propagar enfermedad mientras humanos y Plaga combaten. Las flores de una finca cercana proporcionan el ingrediente que necesita para preparar su siguiente elixir." }
ns.Stories[513] = { anchors = { "Faranell", "compuesto" }, text = "Las flores han sido reducidas a un compuesto, pero la fórmula requiere otra aportación. Faranell puede añadir su preparado de descomposición, de modo que la muestra debe llegar a Entrañas." }
ns.Stories[515] = { anchors = { "Lydon", "contaminantes" }, text = "Faranell ha añadido su preparado y explica cómo activar los agentes contaminantes. Lydon necesita recibir tanto la mezcla como los reactivos restantes para continuar el experimento desde Molino Tarren." }
ns.Stories[516] = { anchors = { "Desafío de Beren", "ataque" }, text = "Los informes señalan que unos no muertos preparan un ataque, aunque no precisan bien su ubicación. Allister quiere encontrarlos y adelantarse a la ofensiva antes de que puedan ejecutarla." }
ns.Stories[517] = { anchors = { "elixir", "cerveza" }, text = "Lydon quiere probar su mezcla contagiosa con un objetivo mayor que los animales anteriores. Un barril tomado de Dun Garok le proporcionará el medio que necesita para continuar preparando esa prueba." }
ns.Stories[518] = { anchors = { "Jarra'thol", "ogros" }, text = "Jarra'thol está protegido por los ogros que ocupan Alterac. Melisara quiere debilitar primero sus fuerzas para abrir una oportunidad de castigarlo sin enfrentar a toda la concentración que lo rodea." }
ns.Stories[524] = { anchors = { "prisioneros", "barril contaminado" }, text = "Los granjeros cautivos han quedado a disposición de Lydon tras descartarse una sospecha militar. Quiere utilizar un barril contaminado para convertirlos en sujetos de su experimento con la nueva mezcla." }
ns.Stories[527] = { anchors = { "Varimathras", "infraestructura" }, text = "Darthalia dirige una ofensiva contra los humanos mientras los boticarios desarrollan la nueva peste. El primer ataque busca dañar sus granjas y abastecimiento, convirtiendo a trabajadores y propietarios en objetivos." }
ns.Stories[528] = { anchors = { "campesinos", "Dama Oscura" }, text = "El ataque a las granjas ha hecho huir a los campesinos hacia el sur. Darthalia quiere perseguirlos en los huertos para prolongar la ofensiva y evitar que encuentren refugio entre los cultivos." }
ns.Stories[529] = { anchors = { "Verringtan", "armas" }, text = "La resistencia humana depende de las armas que fabrica el herrero local. Darthalia quiere cortar ese suministro y llevarse hierro que pueda servir a sus fuerzas durante la campaña." }
ns.Stories[530] = { anchors = { "Valdred", "esposa" }, text = "Raleigh culpa a su antiguo amigo Valdred del asesinato de su esposa. La historia del anillo desemboca en una petición de venganza contra quien cree responsable, antes de que pueda refugiarse tras la Muralla de Cringris." }
ns.Stories[532] = { anchors = { "magistrado", "Declaración" }, text = "Los habitantes siguen combatiendo pese a sus pérdidas y se agrupan en torno a sus dirigentes. Darthalia quiere destruir ese liderazgo y sus símbolos políticos para desarticular la resistencia del pueblo." }
ns.Stories[533] = { anchors = { "Gol'dir", "Hermandad" }, text = "Los informes sugieren que Gol'dir ha sido trasladado entre captores humanos. Un campamento cercano concentra ahora la búsqueda y puede contener documentos que permitan precisar dónde permanece encerrado." }
ns.Stories[535] = { anchors = { "cerveza", "saber" }, text = "Valik está herido y cree que su visitante acabará matándolo. Aun así, ofrece información a cambio de una bebida, convirtiendo el pequeño suministro en una oportunidad para continuar la investigación." }
ns.Stories[539] = { anchors = { "Mina Azur", "hierro" }, text = "El registro recuperado identifica la mina como fuente importante de hierro para la Alianza. Darthalia quiere atacar a sus trabajadores y dirigente para responder al apoyo que todavía recibe." }
ns.Stories[541] = { anchors = { "Dun Garok", "Ferrocolina" }, text = "La ayuda enana a los humanos lleva a Darthalia a ampliar su ofensiva. El ataque contra Dun Garok busca castigar esa alianza y detener al capitán que dirige su guarnición." }
ns.Stories[544] = { anchors = { "robaron", "cuarentena" }, text = "Cuatro Renegados huyeron con objetos necesarios para los estudios de sus boticarios. Los magos de Dalaran los mantienen en cuarentena, y Sylvanas exige recuperar los artefactos que sustrajeron de su cámara." }
ns.Stories[545] = { anchors = { "Dalaran", "tesoros" }, text = "La desaparición de la barrera deja al descubierto zonas donde podrían conservarse tesoros mágicos. Las patrullas de magos y elementales obstaculizan esa exploración, por lo que se pide reducir sus fuerzas." }
ns.Stories[546] = { anchors = { "calaveras", "Darthalia" }, text = "Samsa envidia a quienes participan en la campaña mientras él permanece de guardia. Quiere ampliar su colección de cráneos humanos y ofrece una recompensa por llevarle los que se obtengan durante los combates." }
ns.Stories[547] = { anchors = { "Dun Garok", "espada" }, text = "Humbert perdió su equipo mientras vigilaba Dun Garok y sospecha de los exploradores enanos. Recuperar su espada exige buscar entre las fuerzas de la guarnición que pudo llevársela." }
ns.Stories[549] = { anchors = { "Hermandad", "Durnholde" }, text = "Las autoridades de Sylvanas declaran al Sindicato enemigo y ofrecen recompensas por combatirlo. Sus fuerzas se reúnen en las ruinas de Durnholde, donde la orden dirige la respuesta de los Renegados." }
ns.Stories[550] = { anchors = { "mención", "Varimathras" }, text = "Darthalia ha redactado una recomendación por tu participación en la batalla. Llevarla a Varimathras permite comunicar al alto mando el servicio que considera merecedor de reconocimiento dentro de las fuerzas de los Renegados." }
ns.Stories[552] = { anchors = { "Helcular", "Vara" }, text = "Thaivand busca vengar a Helcular, muerto durante un ritual y enterrado por los humanos. Antes de preparar la represalia necesita recuperar su vara del refugio que ahora ocupan los yetis." }
ns.Stories[553] = { anchors = { "Helcular", "llamas" }, text = "La vara debe cargarse con tres llamas ceremoniales antes de llevarla a la tumba. Thaivand utiliza ese rito como medio de venganza contra Costasur, donde yace el cuerpo de su maestro." }
ns.Stories[556] = { anchors = { "Dalaran", "talismanes" }, text = "Los magos de Dalaran emplean fichas para controlar a los elementales. Voidglare quiere estudiar esos objetos y necesita muestras, preferiblemente obtenidas en un lugar menos peligroso que la propia ciudad." }
ns.Stories[557] = { anchors = { "brazales", "elemental" }, text = "Los brazales que llevan los elementales complementan las fichas de control ya reunidas. Bel'varil quiere adelantarse a las necesidades del investigador y conseguir muestras del vínculo que los mantiene al servicio de los magos." }
ns.Stories[566] = { anchors = { "Vardus", "Hermandad" }, text = "Darthalia considera al barón Vardus un dirigente del Sindicato responsable de crímenes contra los Renegados. Su recompensa ordena buscarlo en Alterac y aportar una prueba que confirme la muerte del objetivo." }
ns.Stories[567] = { anchors = { "Darthalia", "suministros" }, text = "Darthalia ofrece recompensas por varios habitantes de Trabalomas acusados de atacar a los Renegados y sus suministros. Se esconden en la región, y la orden exige confirmar la muerte de cada objetivo." }
ns.Stories[590] = { anchors = { "carta", "dinero" }, text = "Calvin Montesco niega deberte dinero y rechaza la carta que presentas como reclamación. Su respuesta provoca un enfrentamiento en Camposanto: tendrás que vencerlo para resolver la disputa por el pago." }
ns.Stories[676] = { anchors = { "Sentencia", "ogros" }, text = "Sentencia necesita ayuda frente a sus atacantes, pero se exige comprobar primero la preparación de los voluntarios. Los ogros de Arathi ofrecen una prueba antes de incorporarse a la defensa del puesto." }
ns.Stories[1013] = { anchors = { "Libro de Ur", "mundos" }, text = "El libro de Ur conserva estudios de otros mundos que interesan a ciertos Renegados. Su destinatario quiere incorporarlo a su colección y pide recuperarlo del castillo donde permanece guardado." }
ns.Stories[1014] = { anchors = { "Arugal", "bastión" }, text = "Los Renegados consideran que Arugal impide controlar Argénteos como enclave estratégico. Te encargan enfrentarlo en su castillo mientras su mando se ocupa de erradicar la magia que ha causado tantos problemas en el bosque." }
ns.Stories[1051] = { anchors = { "Vishas", "anillo" }, text = "Vorrel agoniza tras semanas de tortura y desea vengarse de Vishas. Su verdugo entregó a Nancy el anillo que le robó; recuperarlo permitirá cumplir la petición de devolverlo a su esposa Monika." }
ns.Stories[1066] = { anchors = { "Ventura", "sangre inocente" }, text = "Un boticario quiere volver dóciles a los trabajadores de la Compañía Ventura mediante una toxina. Para prepararla necesita sangre de inocentes que los magos del Sindicato conservan para sus propios fines oscuros." }
ns.Stories[1067] = { anchors = { "toxina", "Zamah" }, text = "La toxina está preparada, pero Zamah debe diseñar una forma de administrarla que aproveche sus efectos. Llevarla a Cima del Trueno continúa el plan contra la Compañía Ventura antes de probarlo sobre el terreno." }
ns.Stories[1098] = { anchors = { "Adamant", "Vincent" }, text = "Dos mortacechadores no han regresado de investigar el castillo antes de un asalto. Encontrarlos y prestarles ayuda si la necesitan busca recuperar el informe del que dependen los preparativos de los Renegados." }
ns.Stories[1103] = { anchors = { "Islen", "sapta" }, text = "Tiev puede ayudarte a volver a ver al espíritu de agua pura. Necesita una sapta de Islen como prueba de tu preparación y está dispuesto a retrasar su propia ofrenda para facilitar ese nuevo encuentro." }
ns.Stories[1358] = { anchors = { "Helbrim", "Kalimdor" }, text = "Helbrim estudia cómo afectan las toxinas de Lordaeron a las bestias de Kalimdor. Le llevas muestras para ampliar esa investigación y conectar el trabajo de los boticarios a ambos lados del mar." }
ns.Stories[1359] = { anchors = { "corazones", "Zinge" }, text = "Los corazones recuperados presentan una toxicidad que sorprende incluso a los boticarios. Llevas muestras a Zinge para que las estudie con más detalle y determine qué explica esa anomalía." }
ns.Stories[1361] = { anchors = { "Regthar", "Desolace" }, text = "Regthar recluta agentes de la Horda para una misión en Desolace. Quienes quieran ofrecerse deben buscarlo en Los Baldíos, preparados para internarse en una tierra marcada por la guerra y sus peligros." }
ns.Stories[1470] = { anchors = { "conocimiento", "siervo" }, text = "Tu instructor considera que el conocimiento permite someter a los poderes oscuros, en lugar de quedar a su merced. Reúnes materiales para comenzar una lección sobre cómo vincular un siervo a tu voluntad." }
ns.Stories[1471] = { anchors = { "abisario", "dominarlo" }, text = "Invocar al abisario no basta: tu formación exige demostrar que puedes dominarlo. La prueba enfrenta tu voluntad y tu magia a la criatura que pretendes convertir en un siervo." }
ns.Stories[1472] = { anchors = { "súcubo", "corazones" }, text = "Los sayaad devoran almas y dominan voluntades; sus hembras son conocidas como súcubos y sus machos como íncubos. Tu instructor pretende atraer a uno con corazones de mortales puros y bondadosos antes de intentar someterlo. Godrick Farsan puede ayudarte a encontrar esa inquietante carnada." }
ns.Stories[1473] = { anchors = { "Egalin", "grimorio" }, text = "El conocimiento para invocar un abisario está en un grimorio robado por un agente escarlata. Recuperarlo permitirá continuar tu formación, pero tu maestro advierte que esa criatura puede destruir a quien no consiga controlarla." }
ns.Stories[1474] = { anchors = { "súcubo", "Círculo" }, text = "Los materiales ya permiten abrir una puerta para el súcubo. Tu prueba consiste en vencer sus encantos y demostrar el dominio necesario antes de aprender a invocarlo como servidor." }
ns.Stories[1476] = { anchors = { "Dalin", "Comar" }, text = "Dalin Forjador cuida de los refugiados, mientras Corma Villardo permanece fiel a su amor perdido. Esas virtudes los convierten en víctimas del ritual destinado a atraer a una súcubo. Llevar sus corazones a Carendin Halgar transformaría su bondad y devoción en carnada para tu formación como brujo." }
ns.Stories[1478] = { anchors = { "Halgar", "instrucción" }, text = "Carendin Halgar quiere ocuparse de la siguiente etapa de tu aprendizaje. La convocatoria a Entrañas reconoce tus progresos y te acerca a conocimientos de brujo que todavía no has recibido." }
ns.Stories[1712] = { anchors = { "Ciclonio", "corazón" }, text = "Bath’rah lleva tiempo esperando a alguien capaz de vencer a Ciclonio. Reunir los materiales de invocación demostrará tu capacidad como guerrero y permitirá intentar obtener un corazón cuyo poder promete incorporar a un arma." }
ns.Stories[1713] = { anchors = { "Ciclonio", "ritual" }, text = "Bath’rah está listo para invocar a Ciclonio. Debes afrontar al señor del viento y conseguir su corazón, pues el ritual busca aprovechar ese poder para crear el arma prometida durante tu prueba." }
ns.Stories[1803] = { anchors = { "libro del conciliábulo", "páginas" }, text = "Casi la mitad de las páginas del tomo fueron arrancadas y el resto desapareció durante un traslado. Los rumores sobre centauros y el cargamento perdido en la costa ofrecen dos vías para reunir el texto." }
ns.Stories[1805] = { anchors = { "Strahad", "varas" }, text = "El cartógrafo ha estudiado el tomo y transmite una nueva necesidad de Strahad. Conseguir varas de canalización de los orcos Faucedraco permitirá preparar la participación de sus acólitos en la invocación que estás aprendiendo." }
ns.Stories[1818] = { anchors = { "Dillinger", "valor" }, text = "Dillinger busca a un guerrero dispuesto a demostrar su valor al servicio de la Dama Oscura. La convocatoria te lleva a una nueva prueba con la Guardia de la Muerte en Rémol." }
ns.Stories[1819] = { anchors = { "Ulag", "Rey Exánime" }, text = "Los Renegados capturaron a Ulag con la esperanza de romper el vínculo que todavía lo sometía al Rey Exánime. La investigación fracasó y ahora te encargan abrir su prisión para enfrentarlo, poniendo fin a ese intento fallido de liberación." }
ns.Stories[1820] = { anchors = { "Coleman", "venganza" }, text = "Después de probar tu valor, te envían con Coleman Farthing. Busca a un guerrero que actúe contra los enemigos de los Renegados y también sea instrumento de su venganza personal." }
ns.Stories[1821] = { anchors = { "Agamand", "reliquias" }, text = "Coleman culpa a los Agamand, sus antiguos empleadores, de su propia muerte. Quiere apropiarse de las armas familiares para arrebatarles sus últimos símbolos de honor. Recuperarlas de la cripta es una represalia personal que exige entrar en territorio custodiado por la Plaga." }
ns.Stories[1846] = { anchors = { "musleras", "Faucedraco" }, text = "Velora necesita huesos muy resistentes para fabricar la protección de tus piernas. Los orcos Faucedraco pueden proporcionar el material, pero deberás comprobar su solidez antes de llevarlo a una forja que no admite piezas frágiles." }
ns.Stories[1881] = { anchors = { "Anastasia", "mago de los Renegados" }, text = "Anastasia tiene un encargo apropiado para tus aptitudes mágicas. La convocatoria a Entrañas inicia una nueva etapa de tu servicio como mago de los Renegados, aunque todavía debes conocer los detalles de la tarea." }
ns.Stories[1882] = { anchors = { "Balnir", "flores" }, text = "Los magos de los Renegados quieren medir cuánto se extendió la corrupción por Tirisfal. Las flores de la Hacienda Balnir sirven como muestras para estudiar el alcance de esa magia destructiva sobre la vida del lugar." }
ns.Stories[1885] = { anchors = { "Carkad", "llamada" }, text = "Mennet Carkad se ha interesado por ti y exige una reunión. Te diriges a conocer el encargo de alguien cuya autoridad hace que ignorar la convocatoria pueda tener consecuencias, sin saber todavía qué te pedirá." }
ns.Stories[1899] = { anchors = { "libro de contabilidad", "información" }, text = "Tu contacto señala el libro de contabilidad de Astor que contiene la información buscada por tus superiores. Entregarlo a Mennet Carkad permitirá completar este intercambio. Además, el contacto prefiere que sigas actuando como intermediario si deciden continuar el acuerdo." }
ns.Stories[1943] = { anchors = { "Deino", "Orgrimmar" }, text = "Deino, una maga trol de Orgrimmar, solicita tu ayuda. Su convocatoria conduce a la logia donde reside para conocer directamente qué tarea necesita confiarte en la ciudad." }
ns.Stories[1960] = { anchors = { "Algernon", "invisibles" }, text = "Unas criaturas mágicas invisibles están alterando la tienda de Algernon. Tu investigación busca hacerlas visibles y capturarlas para comprender qué está ocurriendo, en lugar de dejar sin explicación el fenómeno." }
ns.Stories[1961] = { anchors = { "togas", "gemas" }, text = "Tu primera toga mágica debe representar tanto tu condición como lo que aprendiste a hacer. Reúnes materiales cargados de maná para que el sastre pueda confeccionar esa prueba visible de tus progresos." }
ns.Stories[2480] = { anchors = { "veneno", "toxina" }, text = "Hinott está fascinado por el veneno que te afecta y quiere examinarlo. Su estudio puede servir tanto para buscar tu cura como para enseñarte a utilizar esa clase de toxinas." }
ns.Stories[3001] = { anchors = { "Strahad", "invocación" }, text = "Tu aprendizaje de invocación necesita ahora otro maestro. Strahad posee conocimientos más avanzados y vive en Trinquete; buscarlo permite continuar la formación con alguien cuya fuerza no debe juzgarse solo por su aspecto." }
ns.Stories[3095] = { anchors = { "pergamino", "Dannal" }, text = "Dannal te envió un mensaje mientras colaborabas contra la Plaga. Leerlo y responder a la convocatoria conecta tus primeras tareas en Camposanto con el aprendizaje específico del camino de guerrero." }
ns.Stories[3096] = { anchors = { "pergamino", "Trias" }, text = "El instructor David Trias te hizo llegar un mensaje. La convocatoria te permite comenzar a desarrollar las técnicas de pícaro que acompañarán tus primeras misiones entre los Renegados." }
ns.Stories[3097] = { anchors = { "pergamino", "Duesten" }, text = "Duesten te envió un mensaje para orientar tu formación como sacerdote. Después de tus primeras tareas contra la Plaga, te toca atender la convocatoria de quien puede enseñarte a ejercer tus capacidades espirituales." }
ns.Stories[3098] = { anchors = { "pergamino", "Isabella" }, text = "Isabella reclama tu atención como instructora de magos. El mensaje enlaza tu servicio inicial en Camposanto con el estudio de las técnicas que vas a necesitar para dominar tu magia." }
ns.Stories[3099] = { anchors = { "pergamino", "Maximillion" }, text = "Maximillion quiere ponerse en contacto contigo para guiar tu formación como brujo. Su mensaje te presenta una enseñanza específica de clase en medio de tus primeras tareas para los Renegados." }
ns.Stories[3221] = { anchors = { "Renferrel", "corazones" }, text = "Renferrel quiere volver a hablar sobre los corazones de lobo que le entregaste. La investigación continúa después de ayudar a los mortacechadores, aunque el aviso todavía no explica qué encontró." }
ns.Stories[3901] = { anchors = { "esqueletos", "Rey Exánime" }, text = "Las primeras tareas mostraron tu potencial y ahora te ponen frente a enemigos más duros de la Plaga. Esta prueba busca comprobar cómo respondes bajo presión mientras reduces las fuerzas que amenazan Camposanto." }
ns.Stories[3902] = { anchors = { "reclutas", "equipo" }, text = "Camposanto espera que despierten nuevos Renegados y necesita ropa y equipo para recibirlos. Recuperar suministros abandonados ayuda a que esos reclutas puedan incorporarse a la comunidad con algo de protección." }
ns.Stories[5481] = { anchors = { "Holland", "manos" }, text = "Gordo necesita conseguir hierbas para Holland, pero sus manos no le permiten recogerlas con cuidado. Lo ayudas con esa tarea y llevas el material a su destinatario, dentro del abastecimiento cotidiano de Rémol." }
ns.Stories[5482] = { anchors = { "apocalíseas", "plantas" }, text = "Holland no está recibiendo las plantas que necesita y te pide corregir la recolección. Buscas las hierbas adecuadas cerca de las fosas comunes para que pueda continuar su trabajo, cuidándote de los gnolls que rondan allí." }
ns.Stories[5643] = { anchors = { "Ur'kyo", "ritos" }, text = "Tu instructor considera que llegó el momento de un rito de aprendizaje propio de tu tradición sacerdotal. Te envía con Ur'kyo para conocer una habilidad que puede ayudarte a sobrevivir en tu camino espiritual." }
ns.Stories[5650] = { anchors = { "Kel", "curación" }, text = "Tu instructor quiere que comprendas la curación, además de las Sombras. Ayudas al guardia herido Kel para demostrar que puedes restaurar y fortalecer a quienes protegen Rémol, aplicando ese equilibrio a una necesidad concreta." }
ns.Stories[5651] = { anchors = { "Beryl", "oscuridad" }, text = "La formación sacerdotal de los Renegados insiste en comprender tanto la Luz como las Sombras. Buscas a Beryl para continuar esas lecciones desde la experiencia de un pueblo que recuperó su voluntad después de la corrupción." }
ns.Stories[5657] = { anchors = { "Ur'kyo", "sendero" }, text = "Ur'kyo quiere revisar el camino espiritual que estás recorriendo. La convocatoria te lleva a Orgrimmar para continuar la formación vinculada a tu tradición sacerdotal." }
ns.Stories[5725] = { anchors = { "Hoja Abrasadora", "libros" }, text = "Sylvanas quiere apropiarse de dos libros de hechizos en manos de la Hoja Abrasadora, una secta del Consejo de las Sombras. Te envían a recuperarlos en las cavernas bajo Orgrimmar para entregárselos." }
ns.Stories[5847] = { anchors = { "Claire", "compañero" }, text = "Un vale de bienvenida permite reclamar un pequeño compañero para tus viajes. Debes entregarlo a Claire Willower en Camposanto para recibir el obsequio vinculado a la edición de coleccionista." }
ns.Stories[6321] = { anchors = { "Hadrec", "armas" }, text = "El Sepulcro necesita reemplazar las armas perdidas por sus defensores. Llevas un pedido a la red de suministros de Entrañas para que la lucha contra las amenazas del bosque no deje a la Guardia de la Muerte sin equipo." }
ns.Stories[6322] = { anchors = { "suministros", "Michael" }, text = "El cargamento de armas para El Sepulcro ya está empaquetado. Te ocupas de enviarlo por la ruta de murciélagos para completar el abastecimiento que necesitan los defensores del asentamiento." }
ns.Stories[6323] = { anchors = { "Gordon", "Entrañas" }, text = "La ruta de murciélagos te lleva a Entrañas, donde Gordon puede atender el pedido de armas. Este trayecto es el enlace necesario entre las necesidades de El Sepulcro y quienes pueden preparar sus suministros." }
ns.Stories[6324] = { anchors = { "Sepulcro", "Karos" }, text = "Ya puedes organizar el vuelo de regreso a El Sepulcro porque conoces a su maestro de murciélagos. La ruta permite completar el viaje de suministros entre Entrañas y el puesto que los necesita." }
ns.Stories[6395] = { anchors = { "Marla", "Samuel" }, text = "Samuel sucumbió a la Plaga y mató a Marla, que aun así quiso ser enterrada junto a él. Debes acabar con su vagar y llevar sus restos a la tumba de ella para cumplir aquella última petición." }
ns.Stories[6628] = { anchors = { "pregunta", "tarea" }, text = "La perseverancia demostrada en tu encargo permite continuar como estudiante del saber. Tu maestro ofrece ahora una pregunta y te concede todo el tiempo necesario para reflexionar antes de responder." }
ns.Stories[6681] = { anchors = { "Ravenholdt", "Fahrad" }, text = "Ravenholdt ha observado tus habilidades y ofrece incorporarte como discípulo de su maestro. Antes de entrar en la Liga de Asesinos debes demostrar astucia encontrando la mansión escondida en las colinas de Trabalomas." }
ns.Stories[7321] = { anchors = { "sopa", "tortuga" }, text = "El trabajo impide a tu contacto cazar las tortugas necesarias para su sopa. Conseguir carne y especias permitirá preparar de nuevo su receta secreta, que ofrece enseñarte como muestra de su conocimiento culinario." }
ns.Stories[9265] = { anchors = { "Plaga", "círculos" }, text = "La Plaga estableció un campamento ante las puertas de Entrañas. Investigas sus círculos rúnicos para averiguar qué prepara mientras ayudas a contener a los invasores que amenazan directamente la ciudad." }

